SELECT user_id AS userId, group_id AS groupId, user_name AS userName, user_end_time AS userEndTime FROM mac_user WHERE
user_email = #{account} user_name = #{account}
AND user_pwd = #{pwd} AND user_status = 1 ORDER BY user_id LIMIT 1

SELECT user_id
FROM mac_user
WHERE user_name = #{name}
  AND user_question = #{question}
  AND user_answer = #{answer}
ORDER BY user_id
LIMIT 1
